      await createTestSession(tempDir, SESSION_ID);

      const result = kspec("ralph end-loop", tempDir, {
        env: { KSPEC_SESSION_ID: SESSION_ID },
      });

      expect(result.exitCode).toBe(0);
      expect(result.stdout).toContain("Loop end signal sent");

